Table users {
  id uuid [pk, not null]
  email varchar(255) [unique, note: 'Login email']
}

Table posts {
  id int [pk, increment]
  user_id uuid [ref: > users.id]
  published boolean [default: false]
}

Enum role {
  admin
  member
}

Table auth.users {
  id uuid [pk]
  role role
  indexes {
    (id, role) [unique]
  }
}
